# update_predictions_screen.ps1
# Replaces lib/features/predictions/screens/predictions_screen.dart with the
# new India-focused Prediction Markets UI. Run from the stockpro-frontend
# repo root (where you see the `lib` folder).
# Usage:  powershell -ExecutionPolicy Bypass -File update_predictions_screen.ps1

$ErrorActionPreference = "Stop"

$targetRelPath = "lib\features\predictions\screens\predictions_screen.dart"
$targetPath = Join-Path (Get-Location) $targetRelPath

if (-not (Test-Path (Split-Path $targetPath -Parent))) {
    Write-Host "ERROR: Can't find $targetRelPath from here." -ForegroundColor Red
    Write-Host "Run this script from the stockpro-frontend repo root (the folder that contains 'lib')." -ForegroundColor Yellow
    exit 1
}

$base64Content = ""

$bytes = [Convert]::FromBase64String($base64Content)
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText($targetPath, $utf8NoBom.GetString($bytes), $utf8NoBom)

Write-Host "Updated: $targetRelPath" -ForegroundColor Green
Write-Host "Route '/predictions' and class name PredictionsScreen are unchanged, so main.dart needs no edits." -ForegroundColor Cyan
Write-Host "Next: flutter pub get; flutter run" -ForegroundColor Cyan
